#!/usr/bin/env python3
"""Build skills/ from src/ and shared/.
   - src/<skill>/SKILL.md : source; `{{include: file.md}}` lines are replaced by shared/file.md
   - shared-manifest.json : lazy shared files copied to skills/<skill>/references/shared/
   - src/<skill>/references/* : copied as-is
   --check : build to a temp dir and exit 1 if skills/ differs (someone edited generated files, or forgot to build)."""
import filecmp, json, re, shutil, sys, tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MANIFEST = {k: v for k, v in json.loads((ROOT / "shared-manifest.json").read_text()).items() if not k.startswith("_")}
BANNER = "<!-- GENERATED by scripts/build.py from src/ and shared/. Edit those, not this file. -->\n"
INC = re.compile(r"^\{\{include: ([\w.-]+)\}\}$", re.M)

def build(out: Path):
    for skill, cfg in MANIFEST.items():
        src, dst = ROOT / "src" / skill, out / skill
        dst.mkdir(parents=True)
        text = (src / "SKILL.md").read_text()
        text = INC.sub(lambda m: (ROOT / "shared" / m.group(1)).read_text().rstrip(), text)
        head, body = re.match(r"(---\n.*?\n---\n)(.*)", text, re.S).groups()
        (dst / "SKILL.md").write_text(head + "\n" + BANNER + body)
        if (src / "references").exists():
            shutil.copytree(src / "references", dst / "references")
        if cfg["lazy"]:
            (dst / "references" / "shared").mkdir(parents=True, exist_ok=True)
            for f in cfg["lazy"]:
                shutil.copy2(ROOT / "shared" / f, dst / "references" / "shared" / f)

def same(a: Path, b: Path) -> list:
    c = filecmp.dircmp(a, b); diffs = [f"only in {a.name}: {x}" for x in c.left_only] + [f"only in {b.name}: {x}" for x in c.right_only]
    diffs += [f"differs: {x}" for x in filecmp.cmpfiles(a, b, c.common_files, shallow=False)[1]]
    for d in c.common_dirs: diffs += [f"{d}/{x}" for x in same(a / d, b / d)]
    return diffs

if __name__ == "__main__":
    if "--check" in sys.argv:
        with tempfile.TemporaryDirectory() as td:
            build(Path(td) / "skills")
            diffs = same(Path(td) / "skills", ROOT / "skills") if (ROOT / "skills").exists() else ["skills/ missing"]
        for d in diffs: print("PROBLEM:", d)
        print("build check:", "FAIL" if diffs else "PASS"); sys.exit(1 if diffs else 0)
    shutil.rmtree(ROOT / "skills", ignore_errors=True)
    build(ROOT / "skills")
    for s in MANIFEST:
        n = (ROOT / "skills" / s / "SKILL.md").read_text().count("\n")
        print(f"built {s}: SKILL.md {n} lines, {len(MANIFEST[s]['lazy'])} lazy shared files")
